"use client";

import { Crown, Gift, ShieldCheck } from "lucide-react";
import { userData } from "@/data/profile";
import { cn } from "@/lib/utils";

export default function ProfileHero() {
  const progressPercentage = (userData.loyaltyPoints / userData.pointsToNextTier) * 100;

  return (
    <div className="relative overflow-hidden rounded-[2.5rem] bg-background-muted border border-border p-8 md:p-12 transition-colors duration-300">
      {/* Subtle background pattern - uses foreground color with very low opacity */}
      <div className="absolute inset-0 opacity-[0.03] bg-[radial-gradient(var(--color-foreground)_1px,transparent_1px)] [background-size:20px_20px]" />

      <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center mb-12">
        <div>
          <h1 className="text-3xl md:text-5xl font-black tracking-tighter mb-2 uppercase">
            Welcome back, <span className="text-brand">{userData.name}</span>
          </h1>
          <p className="text-foreground-muted font-medium">
            Manage your account and view your tier status.
          </p>
        </div>

        {/* Brand Mark Badge - Inverted contrast for prestige */}
        <div className="mt-6 md:mt-0 flex items-center gap-2 bg-foreground text-background px-6 py-2.5 rounded-full shadow-xl">
          <span className="font-black tracking-widest text-sm uppercase">{userData.tierName}</span>
          <Crown size={18} />
        </div>
      </div>

      {/* Benefits Icons - Semantic colors */}
      <div className="relative z-10 grid grid-cols-1 md:grid-cols-3 gap-8 mb-12">
        <BenefitItem 
          icon={<Crown size={20} />} 
          text={<>Unlock exclusive <br/> {userData.tierName} Club access</>} 
        />
        <BenefitItem 
          icon={<ShieldCheck size={20} />} 
          text={<>Assured cashback <br/> on every order</>} 
        />
        <BenefitItem 
          icon={<Gift size={20} />} 
          text={<>Win free gifts <br/> for order streaks</>} 
        />
      </div>

      {/* Modern Progress Bar */}
      <div className="relative z-10 max-w-2xl">
        <div className="flex justify-between text-xs mb-3 font-bold uppercase tracking-widest">
          <span className="text-foreground-subtle">Current Points: {userData.loyaltyPoints}</span>
          <span className="text-foreground">Goal: {userData.pointsToNextTier}</span>
        </div>
        
        {/* Track */}
        <div className="h-4 bg-background border border-border rounded-full overflow-hidden p-0.5 shadow-inner">
          {/* Fill - Uses Brand Primary */}
          <div
            className="h-full bg-brand rounded-full transition-all duration-1000 ease-out relative overflow-hidden"
            style={{ width: `${progressPercentage}%` }}
          >
            {/* Shine effect */}
            <div className="absolute inset-0 bg-linear-to-r from-transparent via-white/20 to-transparent animate-[shimmer_2s_infinite]" />
          </div>
        </div>
        
        <p className="mt-6 text-sm text-foreground-muted font-medium">
          Shop <span className="text-foreground font-bold">₹{userData.pointsToNextTier - userData.loyaltyPoints}</span> more to become an X member.{" "}
          <a href="#" className="text-foreground font-bold underline underline-offset-4 hover:text-brand transition-colors decoration-brand/30">
            More Details
          </a>
        </p>
      </div>
    </div>
  );
}

function BenefitItem({ icon, text }: { icon: React.ReactNode, text: React.ReactNode }) {
  return (
    <div className="flex items-center gap-4 group">
      <div className="bg-background border border-border p-3 rounded-2xl text-foreground group-hover:bg-foreground group-hover:text-background transition-all duration-300 shadow-sm">
        {icon}
      </div>
      <span className="text-xs font-bold uppercase tracking-tight leading-tight text-foreground-muted group-hover:text-foreground transition-colors">
        {text}
      </span>
    </div>
  );
}